=== LoginPage.razor ===
@page "/login"
@layout NoAuthMainLayout
@inject IJSRuntime JSRuntime
@inject NavigationManager NavigationManager
@inject Bovis.Interfaces.Configuration.IConfigurationStore ConfigurationStore

<PageTitle>Anmeldeseite</PageTitle>

<h1>Anmeldung</h1>
<BovisContextView Expr="IsAdmin">
    Sie sind als Administrator angemeldet und können nun zur <a href="/">Hauptseite zurückkehren</a>
    <p>
        <button type="button" class="btn btn-primary" @onclick="Logout">Abmelden</button>
    </p>
</BovisContextView>
<BovisContextView Expr="!IsAdmin">
    <div class="mb-3">
        <label for="user" class="form-label">Benutzer</label>
        <input type="text" class="form-control" id="user" @bind="User" />
    </div>
    <div class="mb-3">
        <label for="pass" class="form-label">Passwort</label>
        <input type="password" class="form-control" id="pass" @bind="Pass" />
    </div>
    <button type="button" class="btn btn-primary" @onclick="Login">Anmelden</button>
</BovisContextView>
<script>
    function BovisSetCookie(name, value, days) {
        var expires = "";
        if (days) {
            var date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    }
</script>

@code {
    private async Task SetCookie(string name, string value)
    {
        await JSRuntime.InvokeVoidAsync("BovisSetCookie", name, value, 7);
    }
    public string User { get; set; } = "";
    public string Pass { get; set; } = "";
    public async void Login()
    {
        var loginFallback = new LoginManager(ConfigurationStore.GetConfiguration()?.GetSection("Bovis.Web")?.GetSection("Users"));

        if (loginFallback.Valid(User, Pass, out string Role) && Role == "admin")
        {
            await SetCookie("bovis_auth_cookie", Bovis.Web.Globals.AuthCookie);
            NavigationManager.NavigateTo(NavigationManager.Uri, true);
        }
        else
        {
            await JSRuntime.InvokeVoidAsync("BovisShowAlert", "Benutzername oder Passwort falsch");
        }
    }
    public async void Logout()
    {
        await SetCookie("bovis_auth_cookie", "");
        NavigationManager.NavigateTo(NavigationManager.Uri, true);
    }
}
=== LoginManager.cs ===
// -----------------------------------------------------------------------------
// LoginManager.cs
// -----------------------------------------------------------------------------
// This file defines a simple stub implementation of a login manager used in the
// Bovis.Web namespace. It provides functionality to compute SHA‑1 hashes of
// UTF‑8 encoded strings and to validate a username/password pair against a password database
// thats is loaded from the configuration. The password database is expected to contain entries with the username, the SHA‑1 hash of the password, and the user role. The validation method checks if the provided username exists in the database and if the SHA‑1 hash of the provided password matches the stored hash, returning the user's role if validation is successful.
// -----------------------------------------------------------------------------
using System.Security.Cryptography;
using System.Text;

namespace Bovis.Web
{
    /// <summary>
    /// Represents a minimal login manager with user data loaded from configuration.
    /// It offers a method to validate a user name and password by comparing the
    /// SHA‑1 hash of the supplied password with a stored hash.
    /// </summary>
    public class LoginManager
    {

        // Represents a user entry in the login manager, containing the username, hashed password, and role.
        class UserInfo
        {
            public string Name { get; set; } = string.Empty; 
            public string HashedPassword { get; set; } = string.Empty;
            public string Role { get; set; } = string.Empty;
        }
        // user database loaded from configuration
        List<UserInfo> users=new(); 

        /// <summary>
        /// Construct a LoginManager with user data from config.
        /// </summary>
        /// <param name="config">The config section that contains a list of UserInfo</param>
        public LoginManager(IConfiguration? config)
        {
            // use Bind() to deserialize the user database from the configuration.
            config?.Bind(users); 
        }
        /// <summary>
        /// Computes the SHA1 hash value of the input string encoded as UTF8 as an uppercase hex string.
        /// </summary>
        /// <param name="input">The input string to compute the hash for.</param>
        /// <returns>The SHA1 hash value of the input string.</returns>
        static string ComputeSha1Hash(string input)
        {
            // Convert the input string to a byte array and compute the hash
            byte[] data = Encoding.UTF8.GetBytes(input);
            byte[] hash = SHA1.HashData(data);
            return Convert.ToHexString(hash);
        }

        /// <summary>
        /// Validates the supplied credentials against the user database
        /// </summary>
        /// <param name="user">The username to validate.</param>
        /// <param name="pass">The plaintext password to validate.</param>
        /// <param name="role">An output parameter that will be set to the user's role if validation is successful.</param>
        /// <returns>True if the username matches a user in the configuration and the SHA‑1 hash of the password
        /// matches the stored hash; otherwise, false.</returns>
        public bool Valid(string user, string pass, out string role)
        {
            role = string.Empty; 
            var hashPass = $"sha1:{ComputeSha1Hash(pass)}";
            foreach (var u in users)
            {
                if (u.Name.Equals(user, StringComparison.OrdinalIgnoreCase))
                {
                    if (hashPass.Equals(u.HashedPassword, StringComparison.OrdinalIgnoreCase))
                    {
                        role = u.Role;
                        return true;
                    }
                }
            }
            return false;
        }
    }

}
